def run_with_pty(args, input_data, env_extra=None, timeout=4):
    master_out, slave_out = pty.openpty()
    env = os.environ.copy()
    if env_extra:
        env.update(env_extra)
    proc = subprocess.Popen(
        ["./executable"]+args,
        stdin=subprocess.PIPE,
        stdout=slave_out,
        stderr=subprocess.PIPE,
        env=env,
        text=True,
    )
    os.close(slave_out)
    if input_data:
        proc.stdin.write(input_data)
    proc.stdin.close()
    flags = fcntl.fcntl(master_out, fcntl.F_GETFL)
    fcntl.fcntl(master_out, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    output = ""
    start=time.time()
    while time.time()-start < timeout:
        r,_,_=select.select([master_out], [], [], 0.5)
        if r:
            try:
                data = os.read(master_out, 8192).decode(errors='replace')
                if data:
                    output+=data
                else:
                    break
            except OSError:
                break
        if proc.poll() is not None and not r:
            try:
                while True:
                    data = os.read(master_out, 8192).decode(errors='replace')
                    if not data:
                        break
                    output+=data
            except:
                break
            break
    try:
        os.close(master_out)
    except: pass
    # Check if still running (pager waiting)
    still_running = proc.poll() is None
    if still_running:
        # Send 'q' to quit pager
        # Need to write to pty? But we closed master? Reopen? Actually we need to keep master open to send q.
        # Let's not close before sending q. For now, just kill.
        proc.kill()
        proc.wait()
    else:
        proc.wait(timeout=1)
    try:
        stderr = proc.stderr.read()
        proc.stderr.close()
    except:
        stderr=""
    return proc.returncode, output, stderr, still_running

