    env = os.environ.copy()
    env["PATH"] = path
    env["TERM"] = "xterm"
    proc = subprocess.Popen(["./executable"], stdin=subprocess.PIPE, stdout=slave_out, stderr=subprocess.PIPE, env=env, text=True)
    import os
    os.close(slave_out)
    proc.stdin.write("a,b\n1,2\n")
    proc.stdin.close()
    # read with timeout, no kill immediately
    import select, fcntl, time
    flags = fcntl.fcntl(master_out, fcntl.F_GETFL)
    fcntl.fcntl(master_out, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    out=""
    start=time.time()
    while time.time()-start < 2:
        r,_,_=select.select([master_out], [], [], 0.5)
        if r:
            try:
                data=os.read(master_out,8192).decode(errors='replace')
                if data:
                    out+=data
                else:
                    break
            except: break
        if proc.poll() is not None:
            break
    print(f"PATH={path} poll={proc.poll()} out={repr(out)}")
    # try to interact: send q, read more
    try:
        os.write(master_out, b"q")
    except Exception as e:
        print(f"write q failed {e}")
    time.sleep(0.5)
    # drain
    try:
        while True:
            r,_,_=select.select([master_out], [], [], 0.5)
            if not r:
                break
            data=os.read(master_out,8192).decode(errors='replace')
            if not data:
                break
            out+=data
            print(f"extra {repr(data[:500])}")
            if proc.poll() is not None:
                break
    except Exception as e:
        print(e)
    print(f"final poll {proc.poll()} full out {repr(out)}")
    try:
        err=proc.stderr.read()
        print(f"err {repr(err)}")
    except: pass
    try:
        os.close(master_out)
    except: pass
