// Minimal reimplementation of terminal_size 0.4.3 for offline build
// Provides terminal_size() -> Option<(Width, Height)> checking stdout

pub struct Width(pub u16);
pub struct Height(pub u16);

/// Returns terminal size for stdout, or None if not a tty or size is zero
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(std::io::stdout())
}

/// Returns terminal size for given fd-like object (generic over AsFd)
/// For simplicity, only support Stdout/Stderr/Stdin via raw fd check
pub fn terminal_size_of<T: std::os::unix::io::AsFd>(t: T) -> Option<(Width, Height)> {
    use std::os::unix::io::AsRawFd;
    let fd = t.as_fd().as_raw_fd();
    // Check isatty
    // Use libc::isatty
    if unsafe { libc::isatty(fd) } != 1 {
        return None;
    }
    let mut winsize: libc::winsize = unsafe { std::mem::zeroed() };
    let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) };
    if ret != 0 {
        return None;
    }
    let cols = winsize.ws_col;
    let rows = winsize.ws_row;
    if cols == 0 || rows == 0 {
        return None;
    }
    Some((Width(cols), Height(rows)))
}
