            "ascii" => Style::Ascii,
            "ascii2" => Style::Ascii2,
            "sharp" => Style::Sharp,
            "rounded" => Style::Rounded,
            "reinforced" => Style::Reinforced,
            "markdown" => Style::Markdown,
            "grid" => Style::Grid,
            _ => Style::Sharp,
        }
    }
