fn read_input(file: &Option<String>) -> Result<(Vec<u8>, usize), String> {
    if let Some(path) = file {
        // Read file
        let mut f = match File::open(path) {
            Ok(f) => f,
            Err(e) => return Err(format!("csview: {}\n", e)),
