fn strip_bom(data: &[u8]) -> (Vec<u8>, usize) {
    if data.len() >= 3 && data[0]==0xEF && data[1]==0xBB && data[2]==0xBF {
        (data[3..].to_vec(), 3)
    } else {
        (data.to_vec(), 0)
    }
}

fn read_input(file: &Option<String>) -> Result<(Vec<u8>, usize), String> {
    if let Some(path) = file {
        // Read file
        let mut f = match File::open(path) {
            Ok(f) => f,
