fn main() -> ExitCode {
    let m = cli().get_matches();
    let file: Option<String> = m.get_one::<String>("file").cloned();
    let no_headers = m.get_flag("no-headers");
    let number = m.get_flag("number");
    let tsv = m.get_flag("tsv");
    let delimiter_char: char = m.get_one::<char>("delimiter").copied().unwrap();
    let delimiter: u8 = if tsv { b'\t' } else { delimiter_char as u8 };
    let style = Style::from_str(m.get_one::<String>("style").unwrap());
    let padding: usize = m.get_one::<usize>("padding").copied().unwrap();
    let indent: usize = m.get_one::<usize>("indent").copied().unwrap();
    let sniff: usize = m.get_one::<usize>("sniff").copied().unwrap();
    let header_align = Align::from_str(m.get_one::<String>("header-align").unwrap());
    let body_align = Align::from_str(m.get_one::<String>("body-align").unwrap());
    let disable_pager = m.get_flag("disable-pager");
    let config = Config { no_headers, number, delimiter, style, padding, indent, sniff, header_align, body_align };
    let stdout_is_tty = io::stdout().is_terminal();
    let use_pager = !disable_pager && stdout_is_tty;
    if use_pager {
        match ProcCommand::new("less").stdin(Stdio::piped()).spawn() {
            Ok(mut child) => {
                let stdin_pipe = child.stdin.take().unwrap();
                let _ = run_with_output(file, &config, Box::new(stdin_pipe));
                match child.wait() {
                    Ok(status) => {
                        if status.success() { ExitCode::from(0) }
                        else { ExitCode::from(status.code().unwrap_or(1) as u8) }
                    }
                    Err(_) => ExitCode::from(1),
                }
            }
            Err(_) => {
                return fallback_pager(file, &config);
            }
        }
    } else {
        let stdout = io::stdout();
        let mut out_lock = stdout.lock();
        match run_no_pager(file, &config, &mut out_lock) {
            Ok(()) => ExitCode::from(0),
            Err(code) => ExitCode::from(code),
        }
    }
}

