    fn new(data: &'a [u8], delimiter: u8) -> Self {
        CsvParser { data, delimiter, pos: 0, line: 1, record_index: 0, prev_was_crlf: false, baseline_fields: None }
    }

    fn peek_terminator(&self, pos: usize) -> Option<(usize, bool, bool)> {
        if pos >= self.data.len() { return None; }
        let b = self.data[pos];
        if self.delimiter == b'\n' {
            if b == b'\r' {
                if pos+1 < self.data.len() && self.data[pos+1]==b'\n' {
                    return Some((2, true, true));
                } else {
