fn format_cell(content: &str, col_width: usize, align: Align, padding: usize) -> String {
    // Truncate/pad content to col_width with align (using non-CJK width via unicode-truncate), then add padding spaces on each side
    let padded_inner = content.unicode_pad(col_width, align.to_truncate(), true);
    let mut s = String::new();
    for _ in 0..padding { s.push(' '); }
    s.push_str(&padded_inner);
    for _ in 0..padding { s.push(' '); }
    s
}

fn build_top(col_widths: &[usize], padding: usize, indent: usize, b: &Borders) -> String {
    let mut s = String::new();
    for _ in 0..indent { s.push(' '); }
    s.push(b.top_l);
    for (i,w) in col_widths.iter().enumerate() {
        if i>0 { s.push(b.top_m); }
        let seg = w + 2*padding;
        for _ in 0..seg { s.push(b.horiz); }
