use clap::{Arg, ArgAction, Command, value_parser};
use std::io::{self, Read, Write, IsTerminal};
use std::fs::File;
use std::process::{Command as ProcCommand, Stdio, ExitCode};
use unicode_width::UnicodeWidthStr;
use unicode_truncate::{UnicodeTruncateStr, Alignment as TAlign};

fn cli() -> Command {
    Command::new("csview")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .next_line_help(true)
        .arg(Arg::new("file").value_name("FILE").help("File to view"))
        .arg(Arg::new("no-headers").short('H').long("no-headers").help("Specify that the input has no header row").action(ArgAction::SetTrue))
        .arg(Arg::new("number").short('n').long("number").help("Prepend a column of line numbers to the table").action(ArgAction::SetTrue))
        .arg(Arg::new("tsv").short('t').long("tsv").help("Use '\\t' as delimiter for tsv").action(ArgAction::SetTrue).conflicts_with("delimiter"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").help("Specify the field delimiter").value_name("DELIMITER").default_value(",").value_parser(value_parser!(char)))
        .arg(Arg::new("style").short('s').long("style").help("Specify the border style").value_name("STYLE").default_value("sharp").value_parser(["none", "ascii", "ascii2", "sharp", "rounded", "reinforced", "markdown", "grid"]).ignore_case(true))
        .arg(Arg::new("padding").short('p').long("padding").help("Specify padding for table cell").value_name("PADDING").default_value("1").value_parser(value_parser!(usize)))
        .arg(Arg::new("indent").short('i').long("indent").help("Specify global indent for table").value_name("INDENT").default_value("0").value_parser(value_parser!(usize)))
        .arg(Arg::new("sniff").long("sniff").help("Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit").value_name("LIMIT").default_value("1000").value_parser(value_parser!(usize)))
        .arg(Arg::new("header-align").long("header-align").help("Specify the alignment of the table header").value_name("HEADER_ALIGN").default_value("center").value_parser(["left", "center", "right"]).ignore_case(true))
        .arg(Arg::new("body-align").long("body-align").help("Specify the alignment of the table body").value_name("BODY_ALIGN").default_value("left").value_parser(["left", "center", "right"]).ignore_case(true))
        .arg(Arg::new("disable-pager").short('P').long("disable-pager").help("Disable pager").action(ArgAction::SetTrue))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Style { None, Ascii, Ascii2, Sharp, Rounded, Reinforced, Markdown, Grid }
impl Style {
    fn from_str(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "none" => Style::None,
            "ascii" => Style::Ascii,
            "ascii2" => Style::Ascii2,
            "sharp" => Style::Sharp,
            "rounded" => Style::Rounded,
            "reinforced" => Style::Reinforced,
            "markdown" => Style::Markdown,
            "grid" => Style::Grid,
            _ => Style::Sharp,
        }
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Align { Left, Center, Right }
impl Align {
    fn from_str(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "left" => Align::Left,
            "center" => Align::Center,
            "right" => Align::Right,
            _ => Align::Left,
        }
    }
    fn to_truncate(&self) -> TAlign {
        match self {
            Align::Left => TAlign::Left,
            Align::Center => TAlign::Center,
            Align::Right => TAlign::Right,
        }
    }
}

struct Config {
    no_headers: bool,
    number: bool,
    delimiter: u8,
    style: Style,
    padding: usize,
    indent: usize,
