fn render_all_at_once(header: Option<Vec<String>>, body: Vec<Vec<String>>, col_widths: &[usize], config: &Config, out: &mut dyn Write) -> Result<(), String> {
    fn write_str(out: &mut dyn Write, s: &str) -> Result<(), String> {
        match out.write_all(s.as_bytes()) {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::BrokenPipe => Ok(()),
            Err(e) => Err(format!("csview: {}\n", e)),
        }
    }
    let has_header = !config.no_headers;
    match config.style {
        Style::None => {
            if has_header {
                if let Some(h) = header {
                    let mut cells: Vec<String> = Vec::new();
                    if config.number { cells.push("#".to_string()); }
                    cells.extend(h.clone());
                    let aligns = vec![config.header_align; col_widths.len()];
                    let row_str = build_row_none(&cells, col_widths, &aligns, config.padding, config.indent);
                    write_str(out, &row_str)?;
                }
            }
            for (i, row) in body.iter().enumerate() {
                let mut cells: Vec<String> = Vec::new();
                if config.number { cells.push(format!("{}", i+1)); }
                cells.extend(row.clone());
                let aligns = vec![config.body_align; col_widths.len()];
                let row_str = build_row_none(&cells, col_widths, &aligns, config.padding, config.indent);
                write_str(out, &row_str)?;
            }
            Ok(())
        }
        Style::Ascii2 => {
            let has_body = !body.is_empty();
            if has_header {
                if let Some(h) = header {
                    let mut cells: Vec<String> = Vec::new();
                    if config.number { cells.push("#".to_string()); }
                    cells.extend(h.clone());
                    let aligns = vec![config.header_align; col_widths.len()];
                    let row_str = build_row_ascii2(&cells, col_widths, &aligns, config.padding, config.indent);
                    write_str(out, &row_str)?;
                    if has_body {
                        let sep_str = build_sep_ascii2(col_widths, config.padding, config.indent);
                        write_str(out, &sep_str)?;
                    }
                }
            }
            for (i, row) in body.iter().enumerate() {
                let mut cells: Vec<String> = Vec::new();
                if config.number { cells.push(format!("{}", i+1)); }
                cells.extend(row.clone());
                let aligns = vec![config.body_align; col_widths.len()];
                let row_str = build_row_ascii2(&cells, col_widths, &aligns, config.padding, config.indent);
                write_str(out, &row_str)?;
            }
            Ok(())
        }
        Style::Markdown => {
            let has_body = !body.is_empty();
            if has_header {
                if let Some(h) = header {
                    let mut cells: Vec<String> = Vec::new();
                    if config.number { cells.push("#".to_string()); }
                    cells.extend(h.clone());
                    let aligns = vec![config.header_align; col_widths.len()];
                    let row_str = build_row_markdown(&cells, col_widths, &aligns, config.padding, config.indent);
                    write_str(out, &row_str)?;
                    if has_body {
                        let sep_str = build_sep_markdown(col_widths, config.padding, config.indent);
                        write_str(out, &sep_str)?;
                    }
                }
            }
            for (i, row) in body.iter().enumerate() {
                let mut cells: Vec<String> = Vec::new();
                if config.number { cells.push(format!("{}", i+1)); }
                cells.extend(row.clone());
                let aligns = vec![config.body_align; col_widths.len()];
                let row_str = build_row_markdown(&cells, col_widths, &aligns, config.padding, config.indent);
                write_str(out, &row_str)?;
            }
            Ok(())
        }
        Style::Sharp | Style::Rounded | Style::Reinforced | Style::Ascii => {
            let b = get_borders(config.style).unwrap();
            let top_str = build_top(col_widths, config.padding, config.indent, &b);
            write_str(out, &top_str)?;
            if has_header {
                if let Some(h) = header {
                    let mut cells: Vec<String> = Vec::new();
                    if config.number { cells.push("#".to_string()); }
                    cells.extend(h.clone());
                    let aligns = vec![config.header_align; col_widths.len()];
                    let row_str = build_row(&cells, col_widths, &aligns, config.padding, config.indent, &b);
                    write_str(out, &row_str)?;
                    if !body.is_empty() {
                        let sep_str = build_sep(col_widths, config.padding, config.indent, &b);
                        write_str(out, &sep_str)?;
                    }
                }
            }
            for (i, row) in body.iter().enumerate() {
                let mut cells: Vec<String> = Vec::new();
                if config.number { cells.push(format!("{}", i+1)); }
                cells.extend(row.clone());
                let aligns = vec![config.body_align; col_widths.len()];
                let row_str = build_row(&cells, col_widths, &aligns, config.padding, config.indent, &b);
                write_str(out, &row_str)?;
            }
            let bot_str = build_bottom(col_widths, config.padding, config.indent, &b);
            write_str(out, &bot_str)?;
            Ok(())
